    "guidelinesSubtitle": "उन्नत समुद्री विश्लेषण के लिए स्थान-काल महासागर तापमान बुद्धिमत्ता प्लेटफ़ॉर्म में महारत हासिल करें",
    "stepInstructions": "चरण-दर-चरण परिचालन निर्देश",
    "step1Title": "1. दिनांक सीमा और विश्लेषण विंडो चुनें",
    "step1Desc": "कंट्रोल बार में अपनी प्रारंभ तिथि चुनकर शुरुआत करें। सिस्टम समुद्री क्षेत्रों में लगातार पूर्वानुमान और विश्वसनीय विसंगति का पता लगाने के लिए स्वचालित रूप से एक मजबूत 4-दिवसीय स्थान-काल विश्लेषण विंडो की गणना और सिंक्रनाइज़ करता है।",
    "step2Title": "2. बिंदु-आधारित समुद्री प्रोफाइलिंग",
    "step2Desc": "इन्टरएक्टिव मानचित्र पर कहीं भी क्लिक करें या सटीक अक्षांश और देशांतर निर्देशांक मैन्युअल रूप से दर्ज करें। भूमि निर्देशांकों को उच्च-रिज़ॉल्यूशन तटरेखा मास्क के विरुद्ध स्वचालित रूप से सत्यापित किया जाता है और निकटतम सुरक्षित महासागर ग्रिड बिंदु पर पुनर्निर्देशित किया जाता है।",
    "step3Title": "3. सतह और गहराई के मापदंडों का विश्लेषण करें",
    "step3Desc": "गतिशील साइड पैनल वास्तविक समय के सतह पैरामीटर प्रदर्शित करता है जिसमें समुद्री सतह का तापमान (SST), समुद्री सतह की लवणता (SSS), समुद्री सतह की ऊंचाई (SSH), और पूर्वी/उत्तरी धारा वेग (UO, VO) शामिल हैं, साथ ही एक इंटरेक्टिव गहराई-वार ऊर्ध्वाधर तापमान प्रोफ़ाइल ग्राफ भी है।",
    "step4Title": "4. क्षेत्रीय लेयर मोड और विज़ुअलाइज़ेशन",
    "step4Desc": "निर्देशांक फ़ील्ड को खाली छोड़ते हुए एक विशिष्ट गहराई मान चुनें ताकि व्यापक क्षेत्रीय विज़ुअलाइज़ेशन मोड अनलॉक हो सकें: स्वतंत्र ARGO अवलोकन ग्राउंड ट्रूथ मानचित्र, कॉनफॉर्मर डीप-learning भविष्यवाणियां, और पूर्ण स्थानिक त्रुटि मैपिंग।",
