    "stepInstructions": "ধাপে ধাপে অপারেশনাল নির্দেশাবলী",
    "step1Title": "1. তারিখের পরিসর এবং বিশ্লেষণ উইন্ডো নির্বাচন করুন",
    "step1Desc": "কন্ট্রোল বারে আপনার শুরুর তারিখ বেছে নিয়ে শুরু করুন। সিস্টেম সামুদ্রিক সেক্টর জুড়ে ধারাবাহিক পূর্বাভাস এবং নির্ভরযোগ্য অসঙ্গতি সনাক্তকরণ নিশ্চিত করতে স্বয়ংক্রিয়ভাবে একটি শক্তিশালী ৪ দিনের স্পটিওটেম্পোরাল বিশ্লেষণ উইন্ডো গণনা এবং সিঙ্ক্রোনাইজ করে।",
    "step2Title": "2. পয়েন্ট-ভিত্তিক সামুদ্রিক প্রোফাইলিং",
    "step2Desc": "ইন্টারেক্টিভ মানচিত্রে যেকোনো জায়গায় ক্লিক করুন অথবা সুনির্দিষ্ট অক্ষাংশ এবং দ্রাঘিমাংশ স্থানাঙ্ক ম্যানুয়ালি লিখুন। উচ্চ-রেজোলিউশন উপকূলরেখা মাস্কের বিরুদ্ধে স্থানাঙ্কগুলি স্বয়ংক্রিয়ভাবে যাচাই করা হয় এবং নিকটতম নিরাপদ সমুদ্র গ্রিড বিন্দুতে রিডাইরেক্ট করা হয়।",
    "step3Title": "3. পৃষ্ঠ এবং গভীরতার প্যারামিটার বিশ্লেষণ করুন",
    "step3Desc": "গতিশীল সাইড প্যানেল রিয়েল-টাইম পৃষ্ঠের প্যারামিটারগুলি প্রদর্শন করে যার মধ্যে রয়েছে সমুদ্রের পৃষ্ঠের তাপমাত্রা (SST), সমুদ্রের পৃষ্ঠের লবণাক্ততা (SSS), সমুদ্রের পৃষ্ঠের উচ্চতা (SSH), এবং পূর্বমুখী/উত্তরমুখী স্রোতের বেগ (UO, VO), পাশাপাশি একটি ইন্টারেক্টিভ গভীরতা-ভিত্তিক উল্লম্ব তাপমাত্রা প্রোফাইল গ্রাফ।",
    "step4Title": "4. আঞ্চলিক লেয়ার মোড এবং ভিজ্যুয়ালাইজেশন",
    "step4Desc": "স্থানাঙ্ক ক্ষেত্রগুলি খালি রেখে একটি নির্দিষ্ট গভীরতার মান নির্বাচন করুন যাতে ব্যাপক আঞ্চলিক ভিজ্যুয়ালাইজেশন মোডগুলি আনলক করা যায়: স্বাধীন ARGO পর্যবেক্ষণ গ্রাউন্ড ট্রুথ মানচিত্র, কনভফর্মার ডিপ-লার্নিং পূর্বাভাস এবং নিখুঁত স্থানিক ত্রুটি ম্যাপিং।",
