    "stepInstructions": "దశలవారీ ఆపరేషనల్ సూచనలు",
    "step1Title": "1. తేదీ పరిధి మరియు విశ్లేషణ విండోను ఎంచుకోండి",
    "step1Desc": "కంట్రోల్ బార్‌లో మీ ప్రారంభ తేదీని ఎంచుకోవడం ద్వారా ప్రారంభించండి. సముద్ర రంగాలలో స్థిరమైన అంచనా మరియు విశ్వసనీయ వైరుధ్య గుర్తింపును నిర్ధారించడానికి సిస్టమ్ స్వయంచాలకంగా బలమైన 4-రోజుల స్పాటియోటెమ్టోరల్ విశ్లేషణ విండోను గణిస్తుంది మరియు సింక్రొనైజ్ చేస్తుంది.",
    "step2Title": "2. పాయింట్-ఆధారిత మెరైన్ ప్రొఫైలింగ్",
    "step2Desc": "ఇంటరాక్టివ్ మ్యాప్‌లో ఎక్కడైనా క్లిక్ చేయండి లేదా ఖచ్చితమైన అక్షాంశం మరియు రేఖాంశ కోఆర్డినేట్‌లను మాన్యువల్‌గా నమోదు చేయండి. అధిక-రిజల్యూషన్ తీరప్రాంత మాస్క్‌లకు వ్యతిరేకంగా కోఆర్డినేట్‌లు స్వయంచాలకంగా ధృవీకరించబడతాయి మరియు సమీపంలోని సురక్షిత మహాసముద్ర గ్రిడ్ పాయింట్‌కు మళ్లించబడతాయి.",
    "step3Title": "3. ఉపరితలం & లోతు పారామితులను విశ్లేషించండి",
    "step3Desc": "డైనమిక్ సైడ్ ప్యానెల్ సముద్ర ఉపరితల ఉష్ణోగ్రత (SST), సముద్ర ఉపరితల లవణీయత (SSS), సముద్ర ఉపరితల ఎత్తు (SSH), మరియు తూర్పు/ఉత్తర ప్రవాహ వేగం (UO, VO)తో కూడిన నిజ-సమయ ఉపరితల పారామితులను ప్రదర్శಿಸುತ್ತದೆ, అలాగే ఇంటరాక్టివ్ లోతు-వారీ నిలువు ఉష్ణోగ్రత ప్రొఫైల్ గ్రాఫ్‌ను చూపుతుంది.",
    "step4Title": "4. ప్రాంతీయ లేయర్ మోడ్‌లు & విజువలైజేషన్",
    "step4Desc": "కోఆర్డినేట్ ఫీల్డ్‌లను ఖాళీగా ఉంచుతూ నిర్దిష్ట లోతు విలువను ఎంచుకోండి, తద్వారా సమగ్ర ప్రాంతీయ విజువలైజేషన్ మోడ్‌లు అన్‌లాక్ చేయబడతాయి: స్వతంత్ర ARGO అబ్జర్వేషన్ గ్రౌండ్ ట్రూత్ మ్యాప్‌లు, కన్వ్‌ఫార్మర్ డీప్-లెర్నింగ్ అంచనాలు మరియు సంపూర్ణ ప్రాంతీయ లోపం మ్యాపింగ్.",
