    "platformOverview": "ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅವಲೋಕನ",
    "navigationGuide": "ನ್ಯಾವಿಗೇಷನ್ ಮಾರ್ಗದರ್ಶಿ",
    "guidelinesSubtitle": "ಸುಧಾರಿತ ಸಮುದ್ರ ವಿಶ್ಲೇಷಣೆಗಾಗಿ ಸ್ಪೇಷಿಯೋಟೆಂಪೊರಲ್ ಸಾಗರ ತಾಪಮಾನ ಇಂಟೆಲಿಜೆನ್ಸ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಅನ್ನು ಕರಗತ ಮಾಡಿಕೊಳ್ಳಿ",
    "stepInstructions": "ಹಂತ-ಹಂತದ ಕಾರ್ಯಾಚರಣೆಯ ಸೂಚನೆಗಳು",
    "step1Title": "1. ದಿನಾಂಕ ಶ್ರೇಣಿ ಮತ್ತು ವಿಶ್ಲೇಷಣಾ ವಿಂಡೋವನ್ನು ಆಯ್ಕೆಮಾಡಿ",
    "step1Desc": "ನಿಯಂತ್ರಣ ಪಟ್ಟಿಯಲ್ಲಿ ನಿಮ್ಮ ಪ್ರಾರಂಭ ದಿನಾಂಕವನ್ನು ಆಯ್ಕೆಮಾಡುವ ಮೂಲಕ ಪ್ರಾರಂಭಿಸಿ. ಸಮುದ್ರ ಕ್ಷೇತ್ರಗಳಲ್ಲಿ ಸ್ಥಿರವಾದ ಮುನ್ಸೂಚನೆ ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹ ವೈಪರೀತ್ಯ ಪತ್ತೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು ವ್ಯವಸ್ಥೆಯು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ದೃಢವಾದ 4 ದಿನಗಳ ಸ್ಪೇಷಿಯೋಟೆಂಪೊರಲ್ ವಿಶ್ಲೇಷಣಾ ವಿಂಡೋವನ್ನು ಲೆಕ್ಕಹಾಕುತ್ತದೆ ಮತ್ತು ಸಿಂಕ್ರೊನೈಸ್ ಮಾಡುತ್ತದೆ.",
    "step2Title": "2. ಬಿಂದು-ಆಧಾರಿತ ಸಮುದ್ರ ಪ್ರೊಫೈಲಿಂಗ್",
    "step2Desc": "ಸಂವಾದಾತ್ಮಕ ನಕ್ಷೆಯಲ್ಲಿ ಎಲ್ಲಿಯಾದರೂ ಕ್ಲಿಕ್ ಮಾಡಿ ಅಥವಾ ನಿಖರವಾದ ಅಕ್ಷಾಂಶ ಮತ್ತು ರೇಖಾಂಶ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ಕೈಯால் ನಮೂದಿಸಿ. ಹೆಚ್ಚಿನ ರೆಸಲ್ಯೂಶನ್ ಕರಾವಳಿ ಮುಖವಾಡಗಳ ವಿರುದ್ಧ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪರಿಶೀಲಿಸಲಾಗುತ್ತದೆ ಮತ್ತು ಹತ್ತಿರದ ಸುರಕ್ಷಿತ ಸಾಗರ ಗ್ರಿಡ್ ಬಿಂದುವಿಗೆ ಮರುನಿರ್ದೇಶಿಸಲಾಗುತ್ತದೆ.",
    "step3Title": "3. ಮೇಲ್ಮೈ ಮತ್ತು ಆಳದ ನಿಯತಾಂಕಗಳನ್ನು ವಿಶ್ಲೇಷಿಸಿ",
    "step3Desc": "ಡೈನಾಮಿಕ್ ಸೈಡ್ ಪ್ಯಾನೆಲ್ ಸಮುದ್ರ ಮೇಲ್ಮೈ ತಾಪಮಾನ (SST), ಸಮುದ್ರ ಮೇಲ್ಮೈ ಲವಣಾಂಶ (SSS), ಸಮುದ್ರ ಮೇಲ್ಮೈ ಎತ್ತರ (SSH), ಮತ್ತು ಪೂರ್ವಮುಖಿ/ಉತ್ತರಮುಖಿ ಪ್ರವಾಹ ವೇಗಗಳನ್ನು (UO, VO) ಒಳಗೊಂಡಿರುವ ರಿಯಲ್-ಟೈಮ್ ಮೇಲ್ಮೈ ನಿಯತಾಂಕಗಳನ್ನು ಪ್ರದರ್ಶಿಸುತ್ತದೆ, ಜೊತೆಗೆ ಸಂವಾದಾತ್ಮಕ ಆಳ-ವಾರು ಲಂಬ ತಾಪಮಾನ ಪ್ರೊಫೈಲ್ ಗ್ರಾಫ್ ಅನ್ನು ಹೊಂದಿದೆ.",
    "step4Title": "4. ಪ್ರಾದೇಶಿಕ ಲೇಯರ್ ಮೋಡ್‌ಗಳು ಮತ್ತು ದೃಶ್ಯೀಕರಣ",
    "step4Desc": "ನಿರ್ದೇಶಾಂಕ ಕ್ಷೇತ್ರಗಳನ್ನು ಖಾಲಿಯಾಗಿ ಬಿಟ್ಟು ನಿರ್ದಿಷ್ಟ ಆಳದ ಮೌಲ್ಯವನ್ನು ಆಯ್ಕೆಮಾಡಿ ಇದರಿಂದ ಸಮಗ್ರ ಪ್ರಾದೇಶಿಕ ದೃಶ್ಯೀಕರಣ ಮೋಡ್‌ಗಳನ್ನು ಅನ್‌ಲಾಕ್ ಮಾಡಬಹುದು: ಸ್ವತಂತ್ರ ARGO ವೀಕ್ಷಣೆ ಗ್ರೌಂಡ್ ಟ್ರೂತ್ ನಕ್ಷೆಗಳು, ಕನ್ವ್ಫಾರ್ಮರ್ ಡೀಪ್-ಲರ್ನಿಂಗ್ ಮುನ್ಸೂಚನೆಗಳು ಮತ್ತು ಸಂಪೂರ್ಣ ಪ್ರಾದೇಶಿಕ ದೋಷ ಮ್ಯಾಪಿಂಗ್.",
