    "guidelinesTitle": "ਵੈੱਬ ਦਿਸ਼ਾ-ਨਿਰਦੇਸ਼ ਅਤੇ ਵਰਤੋਂ ਦਸਤਾਵੇਜ਼",
    "platformOverview": "ਪਲੇਟਫਾਰਮਓਵਰਵਿਊ",
    "navigationGuide": "ਨੇਵੀਗੇਸ਼ਨ ਗਾਈਡ",
    "guidelinesSubtitle": "ਉੱਨਤ ਸਮੁੰਦਰੀ ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਸਥਾਨ-ਕਾਲ ਮਹਾਸਾਗਰ ਤਾਪਮਾਨ ਇੰਟੈਲੀਜੈਂਸ ਪਲੇਟਫਾਰਮ ਵਿੱਚ ਮੁਹਾਰਤ ਹਾਸਲ ਕਰੋ",
    "stepInstructions": "ਕਦਮ-ਦਰ-ਕਦਮ ਸੰਚਾਲਨ ਨਿਰਦੇਸ਼",
    "step1Title": "1. ਮਿਤੀ ਸੀਮਾ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ ਵਿੰਡੋ ਚੁਣੋ",
    "step1Desc": "ਕੰਟਰੋਲ ਬਾਰ ਵਿੱਚ ਆਪਣੀ ਸ਼ੁਰੂਆਤੀ ਮਿਤੀ ਚੁਣ ਕੇ ਸ਼ੁਰੂ ਕਰੋ। ਸਿਸਟਮ ਸਮੁੰਦਰੀ ਖੇਤਰਾਂ ਵਿੱਚ ਲਗਾਤਾਰ ਪੂਰਵ-ਅਨੁਮਾਨ ਅਤੇ ਭਰੋਸੇਯੋਗ ਵਿਸੰਗਤੀ ਦਾ ਪਤਾ ਲਗਾਉਣ ਨੂੰ ਯਕੀਨੀ ਬਣਾਉਣ ਲਈ ਆਪਣੇ ਆਪ ਇੱਕ ਮਜ਼ਬੂਤ 4-ਦਿਨ ਸਥਾਨ-ਕਾਲ ਵਿਸ਼ਲੇਸ਼ਣ ਵਿੰਡੋ ਦੀ ਗਣਨਾ ਕਰਦਾ ਹੈ ਅਤੇ ਸਿੰਕ੍ਰੋਨਾਈਜ਼ ਕਰਦਾ ਹੈ।",
    "step2Title": "2. ਬਿੰਦੂ-ਅਧਾਰਿਤ ਸਮੁੰਦਰੀ ਪ੍ਰੋਫਾਈਲਿੰਗ",
    "step2Desc": "ਇੰਟਰਐਕਟਿਵ ਨਕਸ਼ੇ 'ਤੇ ਕਿਤੇ ਵੀ ਕਲਿੱਕ ਕਰੋ ਜਾਂ ਸਹੀ ਅਕਸ਼ਾਂਸ਼ ਅਤੇ ਲੰਬਕਾਰ ਕੋਆਰਡੀਨੇਟਸ ਨੂੰ ਹੱਥੀਂ ਇਨਪੁਟ ਕਰੋ। ਉੱਚ-ਰੈਜ਼ੋਲੂਸ਼ਨ ਤੱਟਵਰਤੀ ਮਾਸਕ ਦੇ ਵਿਰੁੱਧ ਕੋਆਰਡੀਨੇਟਸ ਆਪਣੇ ਆਪ ਤਸدیਕ ਕੀਤੇ ਜਾਂਦੇ ਹਨ ਅਤੇ ਨਜ਼ਦੀਕੀ ਸੁਰੱਖਿਅਤ ਮਹਾਸਾਗਰ ਗਰਿੱਡ ਬਿੰਦੂ 'ਤੇ ਰੀਡਾਇਰੈਕਟ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।",
    "step3Title": "3. ਸਤਹ ਅਤੇ ਡੂੰਘਾਈ ਦੇ ਮਾਪਦੰਡਾਂ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕਰੋ",
    "step3Desc": "ਗਤੀਸ਼ੀਲ ਸਾਈਡ ਪੈਨਲ ਰੀਅਲ-ਟਾਈਮ ਸਤਹ ਪੈਰਾਮੀਟਰ ਪ੍ਰਦਰਸ਼ਿਤ ਕਰਦਾ ਹੈ ਜਿਸ ਵਿੱਚ ਸਮੁੰਦਰੀ ਸਤਹ ਦਾ ਤਾਪਮਾਨ (SST), ਸਮੁੰਦਰੀ ਸਤਹ ਦੀ ਖਾਰਾਪਣ (SSS), ਸਮੁੰਦਰੀ ਸਤਹ ਦੀ ਉਚਾਈ (SSH), ਅਤੇ ਪੂਰਬੀ/ਉੱਤਰੀ ਕਰੰਟ ਵੇਗ (UO, VO) ਸ਼ਾਮਲ ਹਨ, ਨਾਲ ਹੀ ਇੱਕ ਇੰਟਰਐਕਟਿਵ ਡੂੰਘਾਈ-ਵਾਰ ਲੰਬਕਾਰੀ ਤਾਪਮਾਨ ਪ੍ਰੋਫਾਈਲ ਗ੍ਰਾਫ ਹੈ।",
    "step4Title": "4. ਖੇਤਰੀ ਪਰਤ ਮੋਡ ਅਤੇ ਵਿਜ਼ੂਅਲਾਈਜ਼ੇਸ਼ਨ",
    "step4Desc": "ਕੋਆਰਡੀਨੇਟ ਫੀਲਡਾਂ ਨੂੰ ਖਾਲੀ ਛੱਡ ਕੇ ਇੱਕ ਖਾਸ ਡੂੰਘਾਈ ਦਾ ਮੁੱਲ ਚੁਣੋ ਤਾਂ ਜੋ ਵਿਆਪਕ ਖੇਤਰੀ ਵਿਜ਼ੂਅਲਾਈਜ਼ੇਸ਼ਨ ਮੋਡ ਅਨਲੌਕ ਹੋ ਸਕਣ: ਸੁਤੰਤਰ ARGO ਨਿਰੀਖਣ ਗ੍ਰਾਉਂਡ ਟਰੂਥ ਨਕਸ਼ੇ, ਕਨਵਫਾਰਮਰ ਡੀਪ-ਲਰਨਿੰਗ ਭਵਿੱਖਬਾਣੀਆਂ, ਅਤੇ ਸੰਪੂਰਨ ਸਥਾਨਕ ਗਲਤੀ ਮੈਪਿੰਗ.",
