    "guidelinesSubtitle": "ଉନ୍ନତ ସାମୁଦ୍ରିକ ବିଶ୍ଳେଷଣ ପାଇଁ ସ୍ଥାନ-କାଳ ମହାସାଗର ତାପମାତ୍ରା ଇଣ୍ଟେଲିଜେନ୍ସ ପ୍ଲାଟଫର୍ମରେ ପାରଙ୍ଗମ ହୁଅନ୍ତୁ",
    "stepInstructions": "ପଦକ୍ଷେପ-ଦ୍ୱାରା-ପଦକ୍ଷେପ କାର୍ଯ୍ୟକ୍ଷମ ନିର୍ଦ୍ଦେଶାବଳୀ",
    "step1Title": "1. ତାରିଖ ପରିସର ଏବଂ ବିଶ୍ଳେଷଣ ୱିଣ୍ଡୋ ଚୟନ କରନ୍ତୁ",
    "step1Desc": "କଣ୍ଟ୍ରୋଲ୍ ବାର୍ ରେ ଆପଣଙ୍କର ଆରମ୍ଭ ତାରିଖ ବାଛିବା ଦ୍ୱାରା ଆରମ୍ଭ କରନ୍ତୁ। ସାମୁଦ୍ରିକ କ୍ଷେତ୍ରଗୁଡ଼ିକରେ କ୍ରମାଗତ ପୂର୍ବାନୁମାନ ଏବଂ ନିର୍ଭରଯୋଗ୍ୟ ବ୍ୟତିକ୍ରମ ଚିହ୍ନଟ ନିଶ୍ଚିତ କରିବାକୁ ସିଷ୍ଟମସ୍ୱୟଂଚାଳିତ ଭାବରେ ଏକ ଦୃଢ଼ 4-ଦିନିଆ ସ୍ଥାନ-କାଳ ବିଶ୍ଳେଷଣ ୱିଣ୍ଡୋ ଗଣନା ଏବଂ ସିଙ୍କ୍ କରେ।",
    "step2Title": "2. ପଏଣ୍ଟ-ଭିତ୍ତିକ ସାମୁଦ୍ରିକ ପ୍ରୋଫାଇଲିଂ",
    "step2Desc": "ଇଣ୍ଟରାକ୍ଟିଭ୍ ମାନଚିତ୍ରରେ ଯେକୌଣସି ସ୍ଥାନରେ କ୍ଲିକ୍ କରନ୍ତୁ କିମ୍ବା ସଠିକ୍ ଅକ୍ଷାଂଶ ଏବଂ ଦ୍ରାଘିମା କୋଅର୍ଡି네ଟ୍ ମାନୁଆଲ୍ ଭାବରେ ଇନପୁଟ୍ କରନ୍ତୁ। ଉଚ୍ଚ-ରିଜୋଲ୍ୟୁସନ୍ କୋଷ୍ଟଲାଇନ୍ ମାସ୍କ ବିରୁଦ୍ଧରେ ଜମି କୋଅର୍ଡିନେଟ୍ଗୁଡ଼ିକ ସ୍ୱୟଂଚାଳିତ ଭାବରେ ଯାଞ୍ଚ କରାଯାଏ ଏବଂ ନିକଟସ୍ଥ ନିରାପଦ ମହାସାଗର ଗ୍ରିଡ୍ ପଏଣ୍ଟକୁ ରିଡାଇରେକ୍ଟ କରାଯାଏ।",
    "step3Title": "3. ପୃଷ୍ଠ ଏବଂ ଗଭୀରତା ପାରାମିଟରଗୁଡ଼ିକ ବିଶ୍ଳେଷଣ କରନ୍ତୁ",
    "step3Desc": "ଡାଇନାମିକ୍ ସାଇଡ୍ ପ୍ୟାନେଲ୍ ପ୍ରକୃତ-ସମୟ ପୃଷ୍ଠ ପାରାମିଟର ପ୍ରଦର୍ଶନ କରେ ଯେଉଁଥିରେ ସି' ସର୍ଫେସ୍ ଟେମ୍ପରେଚର୍ (SST), ସି' ସର୍ଫେସ୍ ସାଲିନିଟି (SSS), ସି' ସର୍ଫେସ୍ ହାଇଟ୍ (SSH), ଏବଂ ପୂର୍ବମୁଖୀ/ଉତ୍ତରମୁଖୀ କରେଣ୍ଟ୍ ଭେଲୋସିଟି (UO, VO) ଏବଂ ଏକ ଇଣ୍ଟରାକ୍ଟିଭ୍ ଗଭୀରତା-ଭିତ୍ତିକ ଭର୍ଟିକାଲ୍ ଟେମ୍ପରେଚର୍ ପ୍ରୋଫାଇଲ୍ ଗ୍ରାଫ୍ ଅନ୍ତର୍ଭୁକ୍ତ।",
    "step4Title": "4. ଆଞ୍ଚଳିକ ସ୍ତର ମୋଡ୍ ଏବଂ ଭିଜୁଆଲାଇଜେସନ୍",
    "step4Desc": "କୋଅର୍ଡିନେଟ୍ ଫିଲ୍ଡଗୁଡ଼ିକୁ ଖାଲି ଛାଡି ଏକ ନିର୍ଦ୍ଦିଷ୍ଟ ଗଭୀରତା ମୂଲ୍ୟ ଚୟନ କରନ୍ତୁ ଯାହା ଦ୍ୱାରା ବ୍ୟାପକ ଆଞ୍ଚଳିକ ଭିଜୁଆଲାଇଜେସନ୍ ମୋଡ୍ ଅନଲକ୍ ହେବ: ସ୍ୱାଧୀନ ARGO ଅବଜର୍ଭେସନ୍ ଗ୍ରାଉଣ୍ଡ ଟ୍ରୁଥ୍ ମାନଚିତ୍ର, କନଭଫର୍ମର ଡିପ୍-ଲର୍ନିଂ ପୂର୍ବାନୁମାନ, ଏବଂ ସମ୍ପୂର୍ଣ୍ଣ ଆଞ୍ଚଳିକ ତ୍ରୁଟି ମ୍ୟାପିଂ।",
