    "stepInstructions": "পৰ্যায়ক্ৰমিক কাৰ্যকৰী নিৰ্দেশাৱলী",
    "step1Title": "1. তাৰিখৰ পৰিসৰ আৰু বিশ্লেষণ উইণ্ডো নিৰ্বাচন কৰক",
    "step1Desc": "কন্ট্ৰোল বাৰত আপোনাৰ আৰম্ভণি তাৰিখ বাছি লৈ আৰম্ভ কৰক। চিস্টেমে সামুদ্ৰিক খণ্ডজুৰি ধাৰাবাহিক পূৰ্বাভাস আৰু নিৰ্ভৰযোগ্য অসঙ্গতি চিনাক্তকৰণ নিশ্চিত কৰিবলৈ স্বয়ংক্ৰিয়ভাৱে এটা শক্তিশালী ৪ দিনীয়া স্থান-কাল বিশ্লেষণ উইণ্ডো গণনা আৰু চিন্দ্ৰোনাইজ কৰে।",
    "step2Title": "2. পইণ্ট-ভিত্তিক সামুদ্ৰিক প্ৰফাইলিং",
    "step2Desc": "ইণ্টাৰেক্টিভ মানচিত্ৰত য'তে ত'তে ক্লিক কৰক অথবা নিখুঁত অক্ষাংশ আৰু দ্ৰাঘিমাংশ স্থানাংক মেনুৱেলী ইনপুট কৰক। উচ্চ-ৰিজ'লিউচন উপকূলীয় মাস্কৰ বিৰুদ্ধে স্থানাংকবোৰ স্বয়ংক্ৰিয়ভাৱে যাঁচ কৰা হয় আৰু নিকটতম নিৰাপদ মহাসাগৰ গ্ৰিড পইণ্টলৈ ৰিডাইৰেক্ট কৰা হয়।",
    "step3Title": "3. পৃষ্ঠ আৰু গভীৰতাৰ পেৰামিটাৰ বিশ্লেষণ কৰক",
    "step3Desc": "ডাইনেমিক চাইড পেনেলখনে প্ৰকৃত সময়ৰ পৃষ্ঠ পেৰামিটাৰ প্ৰদৰ্শন কৰে যাৰ ভিতৰত সাগৰীয় পৃষ্ঠৰ তাপমাত্ৰা (SST), সাগৰীয় পৃষ্ঠৰ লৱণতা (SSS), সাগৰীয় পৃষ্ঠৰ উচ্চতা (SSH), আৰু পূৰ্বমুখী/উত্তৰমুখী সোঁতৰ বেগ (UO, VO) অন্তৰ্ভুক্ত, লগতে এটা ইণ্টাৰেক্টিভ গভীৰতা-ভিত্তিক উলম্ব তাপমাত্ৰা প্ৰ'ফাইল গ্ৰাফো আছে।",
    "step4Title": "4. আঞ্চলিক স্তৰৰ মোড আৰু ভিজুৱাইজেচন",
    "step4Desc": "স্থানাংক ফিল্ডবোৰ খালী ৰাখি এটা নিৰ্দিষ্ট গভীৰতাৰ মান নিৰ্বাচন কৰক যাতে বিস্তৃত আঞ্চলিক ভিজ্যুৱাইজেচন মোড আনলক কৰিব পৰা যায়: স্বত স্বাধীন ARGO নিৰীক্ষণ গ্ৰাউণ্ড ট্ৰুথ মানচিত্ৰ, কনভফৰ্মৰ ডিপ-লাৰ্নিং পূৰ্বাভাস, আৰু সম্পূৰ্ণ স্থানিক ত্ৰুটি মেপিং।",
