    "step1Desc": "کنٹرول بار میں اپنی شروعاتی تاریخ کا انتخاب کرکے آغاز کریں۔ سسٹم سمندری شعبوں میں مستقل پیش گوئی اور قابل اعتماد بے ضابطگی کا پتہ لگانے کو یقینی بنانے کے لیے خود بخود ایک مضبوط 4 روزہ اسپیشیوٹیمپோரل تجزیہ ونڈو کا حساب لگاتا ہے اور مطابقت پذیر کرتا ہے۔",
    "step2Title": "2. پوائنٹ پر مبنی سمندری پروفائلنگ",
    "step2Desc": "انٹرایکٹو نقشے پر کہیں بھی کلک کریں یا درست عرض بلد اور طول بلد کے کوآرڈینٹس دستی طور پر درج کریں۔ اعلی ریزولوشن کوسٹ لائن ماسک کے خلاف کوآرڈینٹس خود بخود تصدیق کیے جاتے ہیں اور قریب ترین محفوظ سمندری گریڈ پوائنٹ پر ری ڈائریکٹ کیے جاتے ہیں۔",
    "step3Title": "3. سطح اور گہرائی کے پیرامیٹرز کا تجزیہ کریں",
