    "stepInstructions": "चरण-दर-चरण परिचालन निर्देश",
    "step1Title": "1. मिति दायरा आ विश्लेषण विन्डो चुनू",
    "step1Desc": "कन्त्रोल बारमे अपनेक सुरुआति मिति चुनैत सुरु करू। सिस्टम समुद्री क्षेत्रसभमे लगातार पूर्वानुमान आ विश्वसनीय विसंगति पत्ता लगाब सुनिश्चित करब लेल स्वचालित रूपेण एकटा मजबुत ४ दिवसीय स्थान-काल विश्लेषण विन्डोको गणना आ सिंक्रनाइज करैत अछि।",
    "step2Title": "2. बिन्दु-आधारित समुद्री प्रोफाइलिंग",
    "step2Desc": "इन्टरएक्टिव म्याप पर कोनो ठाम क्लिक करू वा सटीक अक्षांश आ देशान्तर कोअर्डिनेट्स मैन्युअली इनपुट करू। उच्च-रिजोल्यूशन कोस्टलाइन मास्कक विरुद्ध भूमि कोअर्डिनेट्स स्वचालित रूपेण सत्यापित कएल जाइत अछि आ नजिकक सुरक्षित महासागर ग्रिड बिन्दु पर रिडाइरेक्ट कएल जाइत अछि।",
    "step3Title": "3. सतह आ गहिराइ पैरामीटरक विश्लेषण करू",
    "step3Desc": "डाइनामिक साइड प्यानल वास्तविक समयक सतह प्यारामिटरसभ प्रदर्शन करैत अछि जाहिमे समुद्री सतह तापमान (SST), समुद्री सतह नुनिलोपन (SSS), समुद्री सतह उचाइ (SSH), आ पूर्वमुखी/उत्तरमुखी धारा वेग (UO, VO) शामिल अछि, साथ ही एकटा इन्टरएक्टिव गहिराइ-वार ठाड तापमान प्रोफाइल ग्राफ सेहो अछि।",
    "step4Title": "4. क्षेत्रीय स्तर मोड आ भिजुअलाइजेशन",
    "step4Desc": "कोअर्डिनेट्स फिल्ड्स खाली छोैत एकटा विशिष्ट गहिराइ मान चुनू जाहिबाट व्यापक क्षेत्रीय भिजुअलाइजेशन मोडसभ अनलक भ सकैत अछि: स्वतन्त्र ARGO अवलोकन ग्राउन्ड ट्रुथ म्याप्स, कन्भफर्मर डिप-लर्निङ पूर्वानुमान, आ पूर्ण स्थानिय त्रुटि म्यापिंग।",
