    "stepInstructions": "चरण-दर-चरण परिचालन निर्देशनहरू",
    "step1Title": "1. मिति दायरा र विश्लेषण विन्डो छान्नुहोस्",
    "step1Desc": "कन्त्रोल बारमा आफ्नो सुरु मिति छानेर सुरु गर्नुहोस्। प्रणालीले समुद्री क्षेत्रहरूमा निरन्तर पूर्वअनुमान र भरपर्दो असङ्गति पत्ता लगाउने सुनिश्चित गर्न स्वचालित रूपमा एक बलियो ४-दिने स्थान-काल विश्लेषण विन्डो गणना र सिङ्क्रोनाइज गर्छ।",
    "step2Title": "2. बिन्दु-आधारित समुद्री प्रोफाइलिङ",
    "step2Desc": "अन्तरक्रियात्मक नक्सामा जहाँसुकै क्लिक गर्नुहोस् वा सटीक अक्षांश र देशान्तर坐标हरू म्यानुअल रूपमा इनपुट गर्नुहोस्। उच्च-रिजोल्युसन कोस्टलाइन मास्क विरुद्ध भूमि coordinatesहरू स्वचालित रूपमा प्रमाणित हुन्छन् र नजिकैको सुरक्षित महासागर ग्रिड बिन्दुमा रिडाइरेक्ट हुन्छन्।",
    "step3Title": "3. सतह र गहिराइ प्यारामिटरहरू विश्लेषण गर्नुहोस्",
    "step3Desc": "डाइनामिक साइड प्यानलले वास्तविक-समय सतह प्यारामिटरहरू प्रदर्शन गर्दछ जसमा समुद्री सतहको तापक्रम (SST), समुद्री सतहको लवणता (SSS), समुद्री सतहको उचाइ (SSH), र पूर्वमुखी/उत्तरमुखी धारा वेग (UO, VO) समावेश छन्, साथै अन्तरक्रियात्मक गहिराइ-वार ठाडो तापक्रम प्रोफाइल ग्राफ पनि छ।",
    "step4Title": "4. क्षेत्रीय लेयर मोडहरू र भिजुअलाइजेशन",
    "step4Desc": "坐标 ಕ್ಷೇತ್ರहरू खाली छोडेर एक विशिष्ट गहिराइ मान छान्नुहोस् ताकि व्यापक क्षेत्रीय भिजुअलाइजेशन मोडहरू अनलक गर्न सकियोस्: स्वतन्त्र ARGO अवलोकन ग्राउन्ड ट्रुथ नक्साहरू, कन्भफर्मर डिप-लर्निङ पूर्वअनुमानहरू, र पूर्ण स्थानिय त्रुटि म्यापिङ।",
