    "step1Desc": "ڪنٽرول بار ۾ پنهنجي شروعاتي تاريخ چونڊڻ سان شروع ڪريو. سسٽم سامونڊي علائقن ۾ لڳاتار اڳڪٿي ۽ قابل اعتماد بي ضابطگي جي سڃاڻپ کي يقيني بڻائڻ لاءِ خودڪار طريقي سان هڪ مضبوط 4 ڏينهن جي اسپيشيو ٽيمپورل تجزياتي ونڊو جو حساب رکي ٿو ۽ هم وقت سازي ڪري ٿو.",
    "step2Title": "2. پوائنٽ تي ٻڌل سامونڊي پروفائلنگ",
    "step2Desc": "انٽرا ايڪٽو نقشي تي ڪٿي به ڪلڪ ڪريو يا درست ويڪرائي ڦاڪ ۽ ڊگھائي ڦاڪ جا ڪوآرڊينيٽس دستي طور تي داخل ڪريو. اعليٰ ريزوليوشن ڪوسٽ لائين ماسڪ جي خلاف ڪوآرڊينيٽس خودڪار طريقي سان تصديق ڪيا وڃن ٿا ۽ ويجھي محفوظ سمنڊ جي گرڊ پوائنٽ تي ريڊائريڪٽ ڪيا وڃن ٿا.",
    "step3Title": "3. سطح ۽ گہرائي جي پيٽرولرز جو تجزيو ڪريو",
    "step3Desc": "ڊائينامڪ سائيڊ پينل حقيقي وقت جي سطح جا پيٽرولرز ڏيکاري ٿو جنهن ۾ سمنڊ جي سطح جو درجه حرارت (SST)، سمنڊ جي سطح جي نمڪيات (SSS)، سمنڊ جي سطح جي اوچائي (SSH)، ۽ اوڀر/اتر طرف ڪرنٽ جو رفتار (UO, VO) شامل آهن، گڏوگڏ هڪ انٽرا ايڪٽو گہرائي جي لحاظ کان عمودي درجه حرارت پروفائل گراف پڻ موجود آهي.",
