    "stepInstructions": "चरण-दर-चरण परिचालन सूचना",
    "step1Title": "1. दिनांक श्रेणी आणि विश्लेषण विंडो निवडा",
    "step1Desc": "कंट्रोल बारमध्ये तुमची सुरुवातीची तारीख निवडून सुरू करा. सागरी क्षेत्रांमध्ये सातत्यपूर्ण अंदाज आणि विश्वासार्ह विसंगती शोधणे सुनिश्चित करण्यासाठी प्रणाली आपोआप एक मजबूत ४-दिवसीय स्थान-काल विश्लेषण विंडोची गणना करते आणि सिंक करते.",
    "step2Title": "2. बिंदू-आधारित सागरी प्रोफाइलिंग",
    "step2Desc": "परस्परसंवादी नकाशावर कुठेही क्लिक करा किंवा अचूक अक्षांश आणि रेखांश निर्देशांक व्यक्तिचलितपणे प्रविष्ट करा. उच्च-प्रदान किनारपट्टीच्या मास्कविरुद्ध भूमी निर्देशांक आपोआप तपासले जातात आणि जवळच्या सुरक्षित महासागर ग्रिड बिंदूवर पुनर्निर्देशित केले जातात.",
    "step3Title": "3. पृष्ठभाग आणि खोलीचे पॅरामीटर्स तपासा",
    "step3Desc": "डायनॅमिक पॅनेल रीअल-टाइम पृष्ठभाग पॅरामीटर्स प्रदर्शित करते जसे की सागरी पृष्ठभाग तापमान (SST), सागरी पृष्ठभाग क्षारता (SSS), सागरी पृष्ठभाग उंची (SSH), आणि पूर्वमुखी/उत्तरमुखी प्रवाह वेग (UO, VO), तसेच परस्परसंवादी खोली-वार उभी तापमान प्रोफाइल आलेख.",
    "step4Title": "4. प्रादेशिक स्तर मोड आणि व्हिज्युअलायझेशन",
    "step4Desc": "निर्देशांक फील्ड रिकामी ठेवून विशिष्ट खोलीचे मूल्य निवडा जेणेकरून सर्वसमावेशक प्रादेशिक व्हिज्युअलायझेशन मोड अनलॉक होतात: स्वतंत्र ARGO निरीक्षण ग्राउंड ट्रूथ नक्शे, कन्व्हफॉर्मर प्रेडिक्शन आणि अचूक प्रादेशिक त्रुटी मॅपिंग.",
