    "stepInstructions": "चरण-दर-चरण परिचालन निर्देश",
    "step1Title": "1. मिति सीमा ते विश्लेषन विंडो चुणो",
    "step1Desc": "कंट्रोल बार च अपनी शुरुआत दी मिति चुणि करी शुरुआत करो। सिस्टम समुद्री क्षेत्रां च लगातार पूर्वानुमान ते विश्वसनीय विसंगति दा पता लागा सुनिश्चित करने लेई स्वचालित रूप कन्नै इक मजबूत 4-दिवसीय स्थान-काल विश्लेषन विंडो दी गनना ते सिंक्रनाइज करदा ऐ।",
    "step2Title": "2. बिंदु-आधारित समुद्री प्रोफाइलिंग",
    "step2Desc": "इंटरएक्टिव्ह नक्शे पर कित्थੈ बी क्लिक करो जां सटीक अक्षांश ते देशान्तर निर्देशांक मैन्युअली इनपुट करो। उच्च-रिजोल्यूशन कोस्टलाइन मास्क दे विरुद्ध भूमि निर्देशांक स्वचालित रूप कन्नै सत्यापित कीते जंदे न ते नेइड़े दे सुरक्षित महासागर ग्रिड बिंदु पर रिडाइरेक्ट कीते जंदे न।",
    "step3Title": "3. सतह ते खोली दे पैरामीटरै दा विश्लेषन करो",
    "step3Desc": "डायनेमिक साइड पैनल वास्तविक समय दे सतह पैरामीटर प्रदरशित करदा ऐ जिस च सी सरफेस टेंपरेचर (SST), सी सरफेस सेलिनीटी (SSS), सी सरफेस हाइट (SSH), ते पूर्वमुखी/उत्तरमुखी धारा वेग (UO, VO) शामिल न, नाल ई इक इंटरएक्टिव खोली-वार लम्बवत तापमान प्रोफाइल ग्राफ बी ऐ।",
    "step4Title": "4. प्रादेशिक लेयर मोड ते विजुअलाइजेशन",
    "step4Desc": "निर्देशांक फील्डै कन्नै खाली छोड़ी करी इक विशिष्ट खोली दा मुल चुणो तां जो व्यापक प्रादेशिक विजुअलाइजेशन मोड अनलॉक होई सकन: स्वतंत्र ARGO अवलोकन ग्राउंड ट्रूथ नक्शे, कन्व्हफार्मर डीप-लर्निंग भविष्यवाणियां, ते पूर्ण प्रादेशिक त्रुटि मॅपिंग।",
