    "stepInstructions": "অহানবা থবকশিং",
    "step1Title": "1. তারিখ অমসুং এনালিসিস উইন্দো খনগৎসি",
    "step1Desc": "কনত্রোল বারদগী অহানবা তারিখ খনদুনা হৌদোক্লু। সিস্তেম অসিনা মেরিন লমদমশিংদা অচুম্বা প্রেডিকশন অমসুং অসুম্না লৈবা ৪-নিগী স্পাসিওটেম্পোরাল এনালিসিস উইন্দো স্বয়ংক্রমী ওইনা ক্যালকুলেত ওন-সিঙ্ক তেই।",
    "step2Title": "2. পোল্ত-বাস্দ মেরিন প্রোফাইলিং",
    "step2Desc": "ইন্তারক্টিভ ম্যাপতা ক্লিফ তৌবিয়ু নত্রগা লাতিচুদ অমসুং লংগিচুদ মশাগী ওইনা থাপ্পিয়ু। কোস্তলাইন মাক্সকা চুনবা ওসান গ্রিদ পোইন্ত্তা রিদাইরেক্ত তেই।",
    "step3Title": "3. সার্ফেস অমসুং দেপ্থ পরামিতর এনালিসিস তৌবিয়ু",
    "step3Desc": "দাইনামিক সাইদ প্যানেলদা সি সার্ফেস তেম্পরেচর (SST), সি সার্ফেস সলিনিটি (SSS), সি সার্ফেস হাইত (SSH), অমসুং কারেন্ত ভেলোসিটি (UO, VO) উবা ফংগনি।",
    "step4Title": "4. রিজিওনেল লেয়র মোদ অমসুং ভিজুৱলাইজেসন",
    "step4Desc": "কোঅর্দিনেত ফিল্ডশিং লাইথোক্লদুনা স্পেসিফিক দেপ্থ মান খনগৎসি: আরগো গ্রাউন্দ ত্রুথ ম্যাপস, কনভফর্মার প্রেডিকশনস, অমসুং এরর মেপিং।",
