    "stepInstructions": "चरणबद्ध परिचालन निर्देश",
    "step1Title": "1. दिनाङ्क-सीमाम् विश्लेषण-विण्डो च चिनुत",
    "step1Desc": "नियन्त्रण-पट्टे स्वस्य आरम्भिक दिनाङ्कं चित्वा आरभत। सिस्टम् सामुद्रिक क्षेत्रेषु सातत्यपूर्णं पूर्वानुमानं विश्वासयोग्यं विपर्यय-ज्ञानं च सुनिश्चितं कर्तुं स्वयमेव एकं दृढं ४-दिवसीय स्थान-काल विश्लेषण-विण्डोम् गणयति सिङ्क्रनाइज् च करोति।",
    "step2Title": "2. बिन्दु-आधारित सामुद्रिक प्रोफाइलिंग",
    "step2Desc": "संवादी मानचत्रे कुत्रचित् अपि क्लिक् कुर्वन्तु अथवा सटीकम् अक्षांशं देशान्तरं च स्वेच्छया प्रविशत। उच्च-रिजोल्यूषन् तटरेखा-मास्कस्य विरुद्धं भूमि-निर्देशाङ्काः स्वयम् सत्याप्यन्ते, समीपस्थे सुरक्षितमहासागरग्रिड-बिन्दौ च प्रेष्यन्ते।",
    "step3Title": "3. पृष्ठस्य गभीरतायाः च पैरामीटर्स् विश्लेषयत",
    "step3Desc": "गतिशील-पार्श्वपटलः वास्तविकसमयस्य पृष्ठपैरामीटर्स् प्रदर्शयति यथा समुद्रपृष्ठतापमानम् (SST), समुद्रपृष्ठलवणता (SSS), समुद्रपृष्ठोचाइः (SSH), तथा च प्राग्/उदीचीधारा-वेगौ (UO, VO), सार्धम् एकस्य संवादी गभीरता-गतोर्ध्वतापमानप्रोफाइल-आलेखेन।",
    "step4Title": "4. प्रादेशिक-स्तर-मोड्स् विजुअलाइजेशनं च",
    "step4Desc": "निर्देशाङ्क-क्षेत्राणि रिक्तानि त्यक्त्वा एकं विशिष्टं गभीरता-मूल्यं चिनुत येन व्यापकप्रादेशिकविजुअलाइजेशन-मोड्स् उद्घाट्यन्ते: स्वतन्त्र-ARGO-अवलोकन-भूत्यथ-मानचित्राणि, कन्भफर्मर-गाढशिक्षण-भविष्यवाणीः, तथा च पूर्णप्रादेशिकत्रुटि-मानचित्रणम्।",
